"""Lifecycle and durable-path handling for one critique review carrier."""

from __future__ import annotations

from pathlib import Path
from typing import Any


def refresh_manifest_integrity(
    support: Any, storage: Any, root: Path, manifest_relative: str
) -> dict[str, Any]:
    """Hash every promoted file after the final lifecycle bytes are written."""
    manifest = support.repo_path(
        root, manifest_relative, label="promoted attempt manifest", require_file=True
    )
    payload = support.load_mapping(manifest)
    if not isinstance(payload, dict):
        raise support.RunReviewError(
            "promotion-readback-failed", "promoted attempt manifest is not a mapping"
        )
    files = payload.get("files")
    if not isinstance(files, dict):
        raise support.RunReviewError(
            "promotion-readback-failed", "promoted attempt manifest has no file map"
        )
    integrity: dict[str, dict[str, Any]] = {}
    for name, relative in sorted(files.items()):
        if not isinstance(name, str) or not isinstance(relative, str):
            raise support.RunReviewError(
                "promotion-readback-failed", "promoted attempt manifest contains a malformed file"
            )
        path = support.repo_path(root, relative, label=f"promoted file {name}", require_file=True)
        integrity[name] = {
            "path": relative,
            "bytes": path.stat().st_size,
            "sha256": support.sha256(path),
        }
    payload["file_integrity"] = integrity
    storage.write_json_atomically(manifest, payload)
    readback = support.load_mapping(manifest)
    if not isinstance(readback, dict) or readback.get("file_integrity") != integrity:
        raise support.RunReviewError(
            "promotion-readback-failed", "promoted attempt manifest integrity did not read back"
        )
    return integrity


def compare_report_stream(support: Any, stream_path: Path, report_path: Path) -> dict[str, Any]:
    """Record whether stdout and the durable report carry the same mapping."""
    stream = support.load_mapping(stream_path)
    report = support.load_mapping(report_path)
    if stream is None or report is None:
        reason = "runner stdout or canonical report is missing or unreadable"
        consistent = False
    elif stream != report:
        reason = "runner stdout differs from the canonical report carrier"
        consistent = False
    else:
        reason = None
        consistent = True
    return {
        "consistent": consistent,
        "reason": reason,
        "runner_stdout_sha256": support.sha256(stream_path) if stream_path.is_file() else None,
        "canonical_report_sha256": support.sha256(report_path) if report_path.is_file() else None,
    }


def failure_carrier(
    packet_module: Any,
    lifecycle: Any,
    *,
    scope: str,
    lens: str,
    error: str,
    code: str,
    details: dict[str, Any],
) -> dict[str, Any]:
    if lifecycle is None:
        return {
            "schema_version": "charness.reviewer_lifecycle.v1",
            "status": "runner-invalid",
            "execution_state": "preflight-blocked",
            "lifecycle_state": "preflight-blocked",
            "reviewer_started": False,
            "delivery_state": "none",
            "verdict_state": "not-applicable",
            "review_verdict": None,
            "classification": None,
            "approval_eligible": False,
            "output": {"state": "none", "approval_eligible": False, "artifacts": []},
            "output_state": "none",
            "failure_identity": None,
            "next_move": "repair the named preflight boundary and rerun; reviewer did not start",
            "runner_returncode": None,
            "runner_status": "runner-invalid",
            "boundary_ok": None,
            "boundary_reason": None,
            "paths": {},
        }
    carrier = lifecycle.build_lifecycle(
        status="runner-invalid", error=error, reviewer_started=False, paths={}
    )
    carrier.update(
        {
            "ok": False,
            "carrier_ok": False,
            "reason_code": code,
            "error": error,
            "details": details,
            "scope": scope,
            "lens": lens,
        }
    )
    for field in packet_module.REFUSAL_DETAIL_FIELDS:
        if field in details:
            carrier[field] = details[field]
    return carrier


def bind_promoted_paths(
    context: dict[str, Any], promoted: dict[str, str], promotion: Any, *, run_dir: Path | None = None
) -> dict[str, str]:
    """Replace runtime-only paths with their durable receipt paths."""
    bound = context.setdefault("paths", {})
    old_paths = dict(bound)
    for name, relative in promoted.items():
        source_key = promotion.SOURCE_KEYS.get(name)
        if source_key is not None:
            bound[source_key] = relative
    worker_report = promoted.get("worker-report.yaml")
    if worker_report is not None:
        runtime_report = old_paths.get("report")
        if runtime_report is not None and runtime_report != worker_report:
            bound["runtime_report"] = runtime_report
        bound["report"] = worker_report
        bound["durable_report"] = worker_report
    for name, source_key in promotion.LOG_SOURCE_KEYS.items():
        relative = promoted.get(name)
        if relative is not None:
            bound[source_key] = relative
    for key, value in list(bound.items()):
        if not isinstance(value, str):
            continue
        path = Path(value)
        if path.parts[:2] == (".charness", "scratch"):
            bound.pop(key, None)
            continue
        if run_dir is not None and path.is_absolute():
            try:
                path.resolve().relative_to(run_dir.resolve())
            except ValueError:
                pass
            else:
                bound.pop(key, None)
    return bound


def rebind_partial_artifacts(
    carrier: dict[str, Any], old_paths: dict[str, str], new_paths: dict[str, str], promotion: Any
) -> None:
    """Keep lifecycle partial-output descriptors usable after scratch cleanup."""
    collections = [carrier.get("partial_outputs")]
    output = carrier.get("output")
    if isinstance(output, dict):
        collections.extend((output.get("artifacts"), output.get("partial_artifacts")))
    for collection in collections:
        if not isinstance(collection, list):
            continue
        for descriptor in collection:
            if not isinstance(descriptor, dict):
                continue
            path = descriptor.get("path")
            if not isinstance(path, str):
                continue
            for key in promotion.LOG_SOURCE_KEYS.values():
                if path == old_paths.get(key) and key in new_paths:
                    descriptor["path"] = new_paths[key]
                    break


def replace_exact_strings(value: Any, replacements: dict[str, str]) -> Any:
    if isinstance(value, dict):
        for key, nested in list(value.items()):
            value[key] = replace_exact_strings(nested, replacements)
        return value
    if isinstance(value, list):
        return [replace_exact_strings(item, replacements) for item in value]
    if isinstance(value, str):
        return replacements.get(value, value)
    return value


def validate_promoted_chain(
    support: Any,
    promotion: Any,
    root: Path,
    attempt: str,
    paths: dict[str, str],
    context: dict[str, Any],
    carrier: dict[str, Any],
) -> dict[str, Any]:
    package = support.package_paths(Path(__file__).parent)
    carrier_validation = support.load_module(
        package["carrier_validation"], "charness_reviewer_worker_carrier_support_finalization"
    )
    retained_inputs = support.load_module(
        Path(__file__).with_name("run_review_recovery_inputs.py"),
        "charness_run_review_recovery_inputs_finalization",
    )
    result = retained_inputs.validate_promoted_chain_integrity(
        root,
        paths,
        carrier,
        {
            "attempt_id": attempt,
            "packet_sha256": context.get("packet_sha256"),
            "reviewed_input_identity_sha256": context.get("reviewed_input_identity_sha256"),
            "parent_receipt_identity": context.get("parent_receipt_identity"),
        },
        support=support,
        carrier_validation=carrier_validation,
        promotion=promotion,
    )
    result.pop("_manifest_approval_eligible", None)
    return result


def require_valid_promoted_chain(
    support: Any,
    approval: bool,
    binding: dict[str, Any],
    promoted_chain: dict[str, Any],
    recovery_validation: dict[str, Any] | None,
) -> tuple[bool, dict[str, Any]]:
    if promoted_chain.get("ok"):
        return approval, binding
    if recovery_validation is None:
        raise support.RunReviewError(
            "promotion-readback-failed",
            f"promoted reviewer chain did not validate: {promoted_chain.get('reason')}",
        )
    return False, {
        **binding,
        "approval": {
            "status": "mismatch",
            "matches": False,
            "reason": "promoted reviewer chain did not validate",
        },
    }


def finalize_carrier(
    support: Any,
    promotion: Any,
    root: Path,
    promotion_attempt: str,
    paths: dict[str, Path],
    context: dict[str, Any],
    carrier: dict[str, Any],
    report: dict[str, Any] | None,
    recovery_validation: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Promote all terminal bytes, then emit paths that survive owner cleanup."""
    old_paths = dict(context.setdefault("paths", {}))
    promoted = promotion.promote_attempt_metadata(
        root,
        promotion_attempt,
        paths,
        report,
        finalize=True,
        expected_identities={
            "packet_sha256": context.get("packet_sha256"),
            "reviewed_input_identity_sha256": context.get("reviewed_input_identity_sha256"),
            "parent_receipt_identity": context.get("parent_receipt_identity"),
        },
        final_carrier=carrier,
        recovery_validation=recovery_validation,
    )
    semantic_replacements: dict[str, str] = {}
    run_dir = paths.get("run_dir")
    source_dir = run_dir / "semantic-input" if run_dir is not None else None
    if source_dir is not None and source_dir.is_dir():
        for source in source_dir.rglob("*"):
            if not source.is_file() or source.is_symlink():
                continue
            relative = source.relative_to(source_dir)
            promoted_key = f"semantic-input/{relative.as_posix()}"
            durable = promoted.get(promoted_key)
            if durable is not None:
                semantic_replacements[support.relative(root, source)] = durable
    if semantic_replacements:
        carrier["semantic_input"] = replace_exact_strings(
            carrier.get("semantic_input"), semantic_replacements
        )
    bound = bind_promoted_paths(context, promoted, promotion, run_dir=run_dir)
    rebind_partial_artifacts(carrier, old_paths, bound, promotion)
    carrier["paths"] = dict(bound)
    summary = promoted.get("lifecycle.yaml")
    if summary is not None:
        promotion.STORAGE.write_promoted_yaml(root, summary, carrier)
        saved_summary = support.load_mapping(root / summary)
        if not isinstance(saved_summary, dict):
            raise support.RunReviewError(
                "promotion-readback-failed",
                "promoted lifecycle carrier could not be read back as a mapping",
            )
        for key in (
            "schema_version",
            "execution_state",
            "lifecycle_state",
            "delivery_state",
            "approval_eligible",
            "identity_check",
            "runner_stream",
        ):
            if key in carrier and saved_summary.get(key) != carrier.get(key):
                raise support.RunReviewError(
                    "promotion-readback-failed",
                    f"promoted lifecycle carrier changed at `{key}` during read-back",
                )
    manifest_path = promoted.get("attempt-manifest.json")
    if manifest_path is not None:
        promotion.refresh_manifest_integrity(root, manifest_path)
    manifest = support.load_mapping(root / manifest_path) if manifest_path else None
    if not isinstance(manifest, dict):
        raise support.RunReviewError(
            "promotion-readback-failed",
            "promoted reviewer attempt manifest could not be read back",
        )
    approval, binding = promotion.approval_for(
        report,
        expected_identities={
            "packet_sha256": context.get("packet_sha256"),
            "reviewed_input_identity_sha256": context.get("reviewed_input_identity_sha256"),
            "parent_receipt_identity": context.get("parent_receipt_identity"),
        },
        final_carrier=carrier,
    )
    if approval is not (carrier.get("approval_eligible") is True):
        raise support.RunReviewError(
            "promotion-readback-failed",
            "promoted reviewer manifest approval does not match the final lifecycle carrier",
        )
    promoted_chain = None
    if approval or recovery_validation is not None:
        promoted_chain = validate_promoted_chain(
            support,
            promotion,
            root,
            promotion_attempt,
            bound,
            context,
            carrier,
        )
        approval, binding = require_valid_promoted_chain(
            support, approval, binding, promoted_chain, recovery_validation
        )
    # This atomic replacement is the commit point. Every fallible lifecycle
    # write and integrity readback above observes a non-approval manifest.
    manifest.update(
        approval_eligible=approval,
        use_class="approval" if approval else "diagnostic-retryable",
        identity_binding="worker-report-bound" if approval else "consumer-required",
        identity_check=binding,
    )
    promotion.STORAGE.write_json_atomically(root / manifest_path, manifest)
    promotion.promote_finalized_closure(root, promotion_attempt, paths)
    return {"promoted_chain": promoted_chain, "manifest": manifest}


def owner_terminal_state(status: str, carrier: dict[str, Any]) -> str:
    """Map reviewer execution state to the scratch owner's explicit terminal state."""
    delivery = carrier.get("delivery_state")
    if status == "runner-timeout" or delivery == "timed-out":
        return "timed-out"
    if status == "runner-interrupted" or delivery == "interrupted":
        return "cancelled"
    if carrier.get("execution_state") == "terminal" and delivery == "findings-received":
        return "succeeded"
    return "failed"

"""Preserve finalized critique carriers beyond a linked worktree's lifetime."""

from __future__ import annotations

from pathlib import Path
from typing import Any


def _primary_worktree(support: Any, root: Path) -> Path:
    """Return the shared repository's primary worktree for a linked checkout."""
    from scripts.core.git_checkout import layout_from_files

    resolved_root = root.resolve()
    layout = layout_from_files(resolved_root)
    if layout is None or layout.git_dir == layout.common_dir:
        return resolved_root

    from scripts.worktree.worktree_audit_lib import run_audit

    audit = run_audit(resolved_root)
    value = audit.get("primary_worktree")
    if not isinstance(value, str) or not value:
        raise support.RunReviewError(
            "promotion-primary-unavailable",
            "linked-worktree review could not resolve the primary worktree",
            details={"worktree_audit": audit},
        )
    primary = Path(value).resolve()
    primary_layout = layout_from_files(primary)
    if (
        primary == resolved_root
        or primary_layout is None
        or primary_layout.git_dir != layout.common_dir
        or primary_layout.common_dir != layout.common_dir
    ):
        raise support.RunReviewError(
            "promotion-primary-unavailable",
            "linked-worktree review resolved an invalid primary worktree",
            details={"primary_worktree": str(primary)},
        )
    return primary


def _tree_files(support: Any, root: Path) -> dict[str, Path]:
    files: dict[str, Path] = {}
    for path in sorted(root.rglob("*")):
        if path.is_symlink():
            raise support.RunReviewError(
                "stale-artifact-refused",
                f"refusing linked-worktree promotion through a symlink: {path}",
            )
        if path.is_dir():
            continue
        if not path.is_file():
            raise support.RunReviewError(
                "stale-artifact-refused",
                f"refusing non-file durable reviewer content: {path}",
            )
        files[path.relative_to(root).as_posix()] = path
    return files


def _verify_tree(support: Any, source: Path, destination: Path) -> None:
    if destination.is_symlink() or not destination.is_dir():
        raise support.RunReviewError(
            "stale-artifact-refused",
            f"refusing to replace primary reviewer attempt: {destination}",
        )
    source_files = _tree_files(support, source)
    destination_files = _tree_files(support, destination)
    if source_files.keys() != destination_files.keys():
        raise support.RunReviewError(
            "stale-artifact-refused",
            f"primary reviewer attempt does not match linked-worktree closure: {destination}",
        )
    for relative, source_path in source_files.items():
        if source_path.read_bytes() != destination_files[relative].read_bytes():
            raise support.RunReviewError(
                "stale-artifact-refused",
                f"primary reviewer attempt conflicts at {destination / relative}",
            )


def _copy_or_verify_tree(
    support: Any, storage: Any, source: Path, destination: Path
) -> None:
    if destination.is_symlink() or (destination.exists() and not destination.is_dir()):
        raise support.RunReviewError(
            "stale-artifact-refused",
            f"refusing to replace primary reviewer attempt: {destination}",
        )
    if destination.exists():
        _verify_tree(support, source, destination)
        return

    destination.mkdir(parents=True)
    try:
        source_files = _tree_files(support, source)
        manifest = source_files.pop("attempt-manifest.json", None)
        for relative, source_path in source_files.items():
            storage.copy_or_verify(source_path, destination / relative)
        if manifest is None:
            raise support.RunReviewError(
                "promotion-readback-failed",
                "finalized reviewer attempt has no attempt manifest",
            )
        # The manifest is the attempt's commit point, so it becomes visible last.
        storage.copy_or_verify(manifest, destination / "attempt-manifest.json")
        _verify_tree(support, source, destination)
    except Exception:
        # This directory did not exist before this promotion. Its partial bytes
        # cannot be a prior consumer's evidence, so remove them before retaining
        # the authoritative scratch run for retry.
        import shutil

        shutil.rmtree(destination, ignore_errors=True)
        raise


def _primary_destination(
    support: Any, primary: Path, relative: Path, *, label: str
) -> Path:
    destination = primary / relative
    try:
        destination.resolve(strict=False).relative_to(primary)
    except ValueError as exc:
        raise support.RunReviewError(
            "path-invalid", f"{label} escaped the primary worktree"
        ) from exc
    return destination


def promote_finalized_closure(
    support: Any,
    storage: Any,
    worker_reports: Path,
    root: Path,
    attempt: str,
    paths: dict[str, Path],
) -> dict[str, str]:
    """Copy one exact packet and attempt closure to the primary worktree."""
    root = root.resolve()
    primary = _primary_worktree(support, root)
    if primary == root:
        return {"status": "current-worktree", "root": str(root)}

    source_attempt = root / worker_reports / attempt
    if not source_attempt.is_dir() or source_attempt.is_symlink():
        raise support.RunReviewError(
            "promotion-readback-failed",
            "finalized linked-worktree reviewer attempt is unavailable",
        )
    packet = paths.get("packet")
    if packet is None or not packet.is_file() or packet.is_symlink():
        raise support.RunReviewError(
            "promotion-readback-failed",
            "finalized linked-worktree review packet is unavailable",
        )
    try:
        packet_relative = packet.relative_to(root)
    except ValueError as exc:
        raise support.RunReviewError(
            "path-invalid", "review packet escaped the linked worktree"
        ) from exc

    destination_attempt = _primary_destination(
        support, primary, worker_reports / attempt, label="reviewer attempt"
    )
    destination_packet = _primary_destination(
        support, primary, packet_relative, label="review packet"
    )
    critique_root = worker_reports.parent
    if not packet_relative.is_relative_to(critique_root):
        if (
            destination_packet.is_symlink()
            or not destination_packet.is_file()
            or destination_packet.read_bytes() != packet.read_bytes()
        ):
            raise support.RunReviewError(
                "promotion-primary-refused",
                "linked-worktree packet outside the critique artifact owner is not present in the primary worktree",
            )

    # Preflight both existing owners before writing either side of the closure.
    if destination_attempt.exists() or destination_attempt.is_symlink():
        _verify_tree(support, source_attempt, destination_attempt)
    if destination_packet.exists() or destination_packet.is_symlink():
        storage.copy_or_verify(packet, destination_packet)

    storage.copy_or_verify(packet, destination_packet)
    _copy_or_verify_tree(support, storage, source_attempt, destination_attempt)
    if destination_packet.read_bytes() != packet.read_bytes():
        raise support.RunReviewError(
            "promotion-readback-failed", "primary review packet changed during read-back"
        )
    _verify_tree(support, source_attempt, destination_attempt)
    return {
        "status": "promoted-to-primary",
        "root": str(primary),
        "packet": packet_relative.as_posix(),
        "attempt": (worker_reports / attempt).as_posix(),
    }

#!/usr/bin/env python3
"""What the debug artifact surface currently SAYS, read once for the whole plan.

A cohesive split, not a spill (the length gate refused one file and forbids an `_extra_lib`
companion): `plan_debug_run` assembles a plan -- required reads, gate packets, next action,
envelope -- and this module answers the questions that plan is assembled FROM. Which record
the current pointer resolves to, whether it is open, whether this run continues it, what the
producer declined, and which prior incidents are worth reading.

`_continues_existing_artifact` living here is the point of the split rather than an accident
of size: the plan's `mode`, its `next_action.kind`, and its `required_reads` each used to
decide it privately from the same two fields, and two bounded rounds found the copies
disagreeing. One module owns the question; the plan asks it.
"""

from __future__ import annotations

import runpy
from pathlib import Path
from types import SimpleNamespace
from typing import Any

MAX_PRIOR_INCIDENTS = 5


def _load_skill_runtime_bootstrap():
    bootstrap = next((ancestor / "skill_runtime_bootstrap.py" for ancestor in Path(__file__).resolve().parents if (ancestor / "skill_runtime_bootstrap.py").is_file()), None)
    if bootstrap is None:
        raise ImportError("skill_runtime_bootstrap.py not found")
    return SimpleNamespace(**runpy.run_path(str(bootstrap)))


SKILL_RUNTIME = _load_skill_runtime_bootstrap()
risk_interrupt_lib = SKILL_RUNTIME.load_repo_module_from_skill_script(__file__, "scripts.gates_support.risk_interrupt_lib")
_scaffold_artifact_lib = SKILL_RUNTIME.load_repo_module_from_skill_script(__file__, "scripts.core.scaffold_artifact_lib")
declarations = SKILL_RUNTIME.load_local_skill_module(__file__, "debug_artifact_declarations")


def _artifact_summary(repo_root: Path, scaffold: dict[str, Any]) -> dict[str, Any]:
    artifact_rel = str(scaffold["artifact_path"])
    artifact_path = repo_root / artifact_rel
    # A SIXTH derivation of the pointer rule used to live here, reimplemented from the
    # published pointer keys rather than by resolving the symlink -- so the single-owner
    # guard, which greps for readlink-shaped spellings, structurally could not see it. The
    # pair below now comes from the owner, which also fixes what a bounded round found: this
    # summary paired a pointer-derived `write_path` with `write_role` copied from the
    # scaffold AFTER its resolved-followup swap, so in that branch it reported a finished
    # resolved record labelled `durable_record`.
    write_rel, write_role, _ = _scaffold_artifact_lib.current_pointer_write_path(
        repo_root, Path(artifact_rel)
    )
    write_path = repo_root / write_rel
    exists = artifact_path.is_file()
    write_exists = write_path.is_file()
    text = artifact_path.read_text(encoding="utf-8") if exists else ""
    line_count = len(text.splitlines()) if exists else 0
    # Resolution lifecycle: an existing current pointer is treated as an OPEN
    # investigation to continue UNLESS it explicitly declares `- Resolution: resolved`.
    # Default open (missing field) keeps same-investigation resume and legacy
    # behavior; only an explicit `resolved` (set at closeout) makes the planner
    # treat the pointer as a closed prior incident instead of a continuation, so a
    # closed artifact stops hijacking a fresh bug.
    resolution = "resolved" if (exists and (declarations.parse_field(text, "Resolution") or "").strip().lower() == "resolved") else "open"
    if exists and scaffold.get("current_pointer_is_symlink"):
        status = "current_pointer_target_exists"
    elif exists:
        status = "current_pointer_exists"
    else:
        status = "missing"
    summary: dict[str, Any] = {
        "path": artifact_rel,
        "exists": exists,
        "resolution": resolution,
        "line_count": line_count,
        "status": status,
        "role": scaffold["artifact_role"],
        "write_path": write_rel,
        "write_exists": write_exists,
        "write_role": write_role,
        "current_pointer_symlink_target": scaffold["current_pointer_symlink_target"],
    }
    summary.update(declarations.risk_summary(artifact_path, risk_interrupt_lib))
    summary["effective_routing"] = _effective_routing(
        repo_root, artifact_path, summary, scaffold
    )
    return summary


def _effective_routing(
    repo_root: Path,
    artifact_path: Path,
    artifact: dict[str, Any],
    scaffold: dict[str, Any],
) -> dict[str, Any]:
    """Compose the artifact's effective risk route once.

    ``risk_summary`` deliberately preserves what the artifact declared, including
    parser diagnostics and pressure. That raw history is not by itself the
    effective route: a resolved forced-risk record that this run does not continue
    is prior memory, so its interrupt and handoff do not route the new artifact.
    The existing matching, allowed implementation handoff can also release a
    resolved record. The current-slice freshness rule belongs to
    ``plan_risk_interrupt`` and is intentionally not replayed here.
    """
    raw_forced = bool(artifact.get("requires_interrupt"))
    scope_established = bool(artifact.get("risk_scope_established", True))
    routing: dict[str, Any] = {
        "risk_interrupt_active": raw_forced,
        "requires_current_artifact_read": raw_forced or not scope_established,
        "reason": "raw-forced-risk" if raw_forced else "no-forced-risk",
    }
    if artifact.get("risk_parse_error") or not scope_established:
        routing["reason"] = "risk-declaration-unreadable"
        return routing
    if not raw_forced or artifact.get("resolution") != "resolved":
        return routing

    def prior_record_route() -> dict[str, Any]:
        if not _continues_existing_artifact(artifact, scaffold):
            routing.update(
                {
                    "risk_interrupt_active": False,
                    "requires_current_artifact_read": False,
                    "reason": "resolved-forced-risk-prior-record-not-continued",
                }
            )
        return routing

    try:
        interrupt = risk_interrupt_lib.parse_debug_interrupt(artifact_path)
    except (risk_interrupt_lib.ValidationError, OSError, UnicodeError) as exc:
        routing.update(
            {
                "reason": "resolved-forced-risk-debug-interrupt-invalid",
                "handoff_error": str(exc),
            }
        )
        return prior_record_route()
    if not interrupt.get("present") or not interrupt.get("forced"):
        routing["reason"] = "resolved-forced-risk-debug-interrupt-incomplete"
        return prior_record_route()

    handoff_artifact = str(interrupt["handoff_artifact"])
    routing["handoff_artifact"] = handoff_artifact
    try:
        handoff = risk_interrupt_lib.parse_spec_interrupt_resolution(
            repo_root / handoff_artifact,
            interrupt_id=str(interrupt["interrupt_id"]),
        )
    except (risk_interrupt_lib.ValidationError, OSError, UnicodeError) as exc:
        routing.update(
            {
                "reason": "resolved-forced-risk-handoff-invalid",
                "handoff_error": str(exc),
            }
        )
        return prior_record_route()

    if handoff["seam_summary"] != interrupt["seam"]:
        routing.update(
            {
                "reason": "resolved-forced-risk-handoff-seam-mismatch",
                "handoff_error": "spec handoff seam summary does not match debug seam",
            }
        )
        return prior_record_route()
    if handoff["chosen_next_step"] != "impl" or handoff["impl_status"] != "allowed":
        routing.update(
            {
                "reason": "resolved-forced-risk-handoff-not-implementation-allowed",
                "handoff_error": "spec handoff must choose impl with Impl Status: allowed",
            }
        )
        return prior_record_route()

    routing.update(
        {
            "risk_interrupt_active": False,
            "requires_current_artifact_read": False,
            "reason": "resolved-with-valid-allowed-handoff",
            "interrupt_id": str(interrupt["interrupt_id"]),
        }
    )
    return routing

def _title_for(path: Path) -> str | None:
    if not path.is_file():
        return None
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("# "):
            return line[2:].strip()
    return None

def _prior_incidents(repo_root: Path, output_dir: str, current_path: str) -> list[dict[str, Any]]:
    directory = repo_root / output_dir
    if not directory.is_dir():
        return []
    current_resolved = (repo_root / current_path).resolve()
    candidates: list[Path] = []
    for pattern in ("debug-*.md", "20*.md"):
        candidates.extend(directory.glob(pattern))
    unique = sorted(set(candidates), key=lambda path: (path.stat().st_mtime, path.name), reverse=True)
    incidents = []
    for path in unique:
        if path.name == "latest.md" or path.resolve() == current_resolved:
            continue
        rel_path = str(path.relative_to(repo_root))
        incidents.append(
            {
                "path": rel_path,
                "title": _title_for(path),
                "mtime": path.stat().st_mtime,
            }
        )
        if len(incidents) >= MAX_PRIOR_INCIDENTS:
            break
    return incidents

def _refusal_keys(scaffold: dict[str, Any]) -> dict[str, Any]:
    """What the producer declined, for every arm that hands back an existing record's path.

    Round 2 found the refusal keys living only on the scaffold branch — the one branch whose
    path is fresh. The three arms that actually name an existing record (continue, and both
    risk arms) carried none, so a run following `next_action` saw an overwrite target with no
    sign that the producer had refused to hand it out.
    """
    if "refused_write_artifact_path" not in scaffold:
        return {}
    return {
        "refused_write_artifact_path": scaffold["refused_write_artifact_path"],
        "refused_write_artifact_subject_key": scaffold["refused_write_artifact_subject_key"],
        "refused_write_artifact_reason": scaffold["refused_write_artifact_reason"],
        "continue_refused_subject_command": _continue_refused_command(scaffold),
    }

def _continue_refused_command(scaffold: dict[str, Any]) -> str:
    evidence = " --evidence-led" if scaffold.get("evidence_mode") else ""
    return (
        "python3 $SKILL_DIR/scripts/plan_debug_run.py --repo-root . "
        f"--subject {scaffold['refused_write_artifact_subject_key']}{evidence}"
    )

def _continues_existing_artifact(artifact: dict[str, Any], scaffold: dict[str, Any]) -> bool:
    """ONE answer to "does this run continue the record the current pointer names".

    The plan's `mode`, its `next_action.kind`, and its `required_reads` each decided this
    independently from the same two fields, which is fine while the rule is one line and wrong
    the moment it grows a third clause: the subject clause landed in `mode` first, and the
    other two kept naming the record the scaffold had declined.

    Only a DECLARED disagreement stops the continue arm. An undeclared invocation is ambiguity,
    and this planner's fail-safe for ambiguity is deliberate and tested — an unparseable or
    missing resolution continues rather than abandoning an open investigation. The scaffold
    still refuses to hand an undeclared run a template write path onto that record, which is
    where the destructive half of the reported defect lived; routing an author to READ and
    continue it is the pre-existing contract and not this slice's to invert.
    """
    if not artifact["exists"] or artifact["resolution"] == "resolved":
        return False
    if scaffold.get("invocation_subject_key") is None:
        # Undeclared: ambiguity, and the fail-safe applies whatever the scaffold's reason was.
        return True
    return scaffold.get("refused_write_artifact_reason") not in (
        _scaffold_artifact_lib.SUBJECT_MATCH_MISMATCH,
        # A DECLARED subject against a target whose own name carries no subject is not
        # ambiguity on the author's side -- they said which investigation this is, and the
        # record cannot confirm it is that one.
        _scaffold_artifact_lib.SUBJECT_MATCH_UNKNOWN,
    )
